  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01, g = 9.81;
  const mNom = 0.725, fMax = 15.5, specScale = fMax / mNom, dragCoeff = 0.42 / mNom;

