  let thrustEst = 0, lastThrust = 0.45;
  let dSlow = { x: 0, y: 0, z: 0 }, dFast = { x: 0, y: 0, z: 0 };
  let intPos = { x: 0, y: 0, z: 0 }, yawInt = 0;
