        dSlow.y += aSlowY * (dRawY - dSlow.y);
        dSlow.z += aSlow * (dRawZ - dSlow.z);

        dFast.x += 0.24 * (dRawX - dFast.x);
        dFast.y += 0.15 * (dRawY - dFast.y);
        dFast.z += 0.24 * (dRawZ - dFast.z);
